mapper.select:
SELECT COMBO_TP , CD , NM , PRNT_CD FROM (
SELECT 'FAMILY' AS COMBO_TP , FAMILY_CD AS CD , FAMILY_NM AS NM , NULL AS PRNT_CD , ROW_NUMBER() OVER (ORDER BY FAMILY_CD) AS SORT_NO FROM TB_FAMILY WHERE 1 = 1 UNION ALL
SELECT 'A' AS COMBO_TP , A_CD AS CD , A_NM AS NM , NULL AS PRNT_CD , ROW_NUMBER() OVER (ORDER BY DECODE(A_CD, 'X', 1, 'Y', 2, 9), A_NM) AS SORT_NO FROM TB_A WHERE FAMILY_CD = #{family}
UNION ALL
SELECT 'B' AS COMBO_TP , B_CD AS CD , B_NM AS NM , A_CD AS PRNT_CD , ROW_NUMBER() OVER (ORDER BY B_CD DESC) AS SORT_NO FROM TB_B WHERE FAMILY_CD = #{family}
UNION ALL
SELECT 'C' AS COMBO_TP , C_CD AS CD , C_NM AS NM , B_CD AS PRNT_CD , ROW_NUMBER() OVER (ORDER BY C_CD) AS SORT_NO FROM TB_C WHERE FAMILY_CD = #{family}
UNION ALL
SELECT 'D' AS COMBO_TP , D_CD AS CD , D_NM AS NM , C_CD AS PRNT_CD , ROW_NUMBER() OVER (ORDER BY D_CD) AS SORT_NO FROM TB_D WHERE FAMILY_CD = #{family}
UNION ALL
SELECT 'E' AS COMBO_TP , E_CD AS CD , E_NM AS NM , D_CD AS PRNT_CD , ROW_NUMBER() OVER (ORDER BY E_CD) AS SORT_NO FROM TB_E WHERE FAMILY_CD = #{family}
UNION ALL
SELECT 'F' AS COMBO_TP , F_CD AS CD , F_NM AS NM , E_CD AS PRNT_CD , ROW_NUMBER() OVER (ORDER BY F_CD) AS SORT_NO FROM TB_F WHERE FAMILY_CD = #{family}
UNION ALL
SELECT 'G' AS COMBO_TP , G_CD AS CD , G_NM AS NM , F_CD AS PRNT_CD , ROW_NUMBER() OVER (ORDER BY G_CD) AS SORT_NO FROM TB_G WHERE FAMILY_CD = #{family}
UNION ALL
SELECT 'H' AS COMBO_TP , H_CD AS CD , H_NM AS NM , NULL AS PRNT_CD , ROW_NUMBER() OVER (ORDER BY H_NM) AS SORT_NO FROM TB_H WHERE FAMILY_CD = #{family} ) ORDER BY COMBO_TP, SORT_NO
